import osproducts = {   "ex333", "ex336", "ex339", "ex342",   "act333", "act336", "act339", "act342"}def getProduct(file):   for ref in products:      if file.find(ref) is not -1:         return "Products.o"   return ""def getRun(file):   vals = file.split(".")   base = vals[0]   run = base + ".run"   obj = base + ".o"   product =  getProduct(file)   return {"file":file, "base":base, "run":run, "obj":obj, "product":product}print("# Generated by FiMake2.py.")comp = "c++ --std=c++11"include = '-I../ShoppingCart01/Headers -I../ShoppingCart03/Headers'root = "."files = os.listdir(root)files = sorted(files)print("\n\nall: ", end="")for file in files:    if not file.endswith(".cpp"):        continue;    zDict = getRun(file)            print(zDict["run"], " ", end="")print()for file in files:    if file.endswith(".cpp"):        print("\n\n#", len(file) * '*')        print("#", file)        print("#", len(file) * '*')        zDict = getRun(file)                print(zDict["run"], ":", zDict["product"], zDict["file"])        print("\t" + comp, include, file, "-o", zDict["run"], zDict["product"])print("\n\nProducts.o: ../ShoppingCart03/LabSolutions/Products.cpp")print("\t" + comp, include, "-c ../ShoppingCart03/LabSolutions/Products.cpp")print("\n\nclean:");for ref in {"*.o", "*.run"}:	print("\trm", ref)print()